begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select plan(9);
insert into auth.users(id, email) values ('11111111-1111-4111-8111-111111111111', 'mira-test-a@example.invalid'), ('22222222-2222-4222-8222-222222222222', 'mira-test-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
select is(public.save_mira_document('{"schemaVersion":1,"profile":{},"entries":[]}', 0, '11111111-1111-4111-8111-111111111111'), 1, 'first save returns revision 1');
select is(public.save_mira_document('{"schemaVersion":1,"profile":{},"entries":[]}', 1, '11111111-1111-4111-8111-111111111111'), 2, 'CAS advances revision');
select throws_ok($$select public.save_mira_document('{"schemaVersion":1,"profile":{},"entries":[]}', 1, '11111111-1111-4111-8111-111111111111')$$, '40001', 'Sync conflict', 'stale revision cannot overwrite data');
select throws_ok($$select public.save_mira_document('{"schemaVersion":99,"profile":{},"entries":[]}', 2, '11111111-1111-4111-8111-111111111111')$$, '22023', 'Invalid document', 'unsupported schema is rejected');
select throws_ok($$insert into public.mira_documents(user_id,payload) values ('11111111-1111-4111-8111-111111111111','{}')$$, '42501', 'permission denied for table mira_documents', 'direct writes are forbidden');
select set_config('request.jwt.claims', '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}', true);
select is((select count(*)::integer from public.mira_documents), 0, 'user B cannot read user A');
select throws_ok($$select public.save_mira_document('{"schemaVersion":1,"profile":{},"entries":[]}',0,'11111111-1111-4111-8111-111111111111')$$, '42501', 'Wrong account', 'account changes cannot save an old document under a new user');
select throws_ok($$select public.consume_mira_ai_request('22222222-2222-4222-8222-222222222222')$$, '42501', 'permission denied for function consume_mira_ai_request', 'clients cannot consume or reset rate limits');
set local role anon;
select throws_ok($$select public.save_mira_document('{"schemaVersion":1,"profile":{},"entries":[]}',0,'11111111-1111-4111-8111-111111111111')$$, '42501', 'permission denied for function save_mira_document', 'anonymous writes are forbidden');
select * from finish();
rollback;
